async function handleDuplicate() {
  setIsDuplicating(true)
  try {
    const result = await duplicateFlashEventAction(event.id)
    if (result.success && result.newEventId) {
      toast.success('Event duplicated — opening editor')
      router.push(`/flash-events/${result.newEventId}/edit`)
