// ── Duplicate ─────────────────────────────────────────────────────────────────

export async function duplicateFlashEventAction(
  eventId: string
): Promise<ActionResult & { newEventId?: string }> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { success: false, error: 'Not authenticated' }
  if (!['owner', 'admin', 'receptionist'].includes(auth.role)) {
    return { success: false, error: 'Insufficient permissions' }
  }

  try {
    const { createClient } = await import('@/lib/supabase/server')
    const supabase = await createClient()

    const rpc = supabase.rpc as unknown as (
      fn: 'duplicate_flash_event',
      args: { p_event_id: string }
    ) => Promise<{ data: string | null; error: { message: string } | null }>

    const { data, error } = await rpc('duplicate_flash_event', { p_event_id: eventId })

    if (error) {
      logger.error({ error, eventId }, 'duplicateFlashEventAction RPC failed')
      return { success: false, error: error.message }
    }

    const newEventId = data
    if (!newEventId) {
      return { success: false, error: 'Failed to duplicate event' }
    }

    const { logAuditAction } = await import('@/lib/audit')
    await logAuditAction(
      auth.user.id,
      'flash_event.duplicated',
      { type: 'flash_event', id: eventId },
      { newEventId },
      auth.studioId
    )

    revalidatePath('/flash-events')
    return { success: true, newEventId }
  } catch (err) {
    logger.error({ err, eventId }, 'duplicateFlashEventAction failed')
    const message = err instanceof Error ? err.message : 'Failed to duplicate event'
    return { success: false, error: message }
  }
}

