export interface CloseOutSummary {
  event_id: string
  completed_count: number
  no_show_count: number
  slot_revenue_cents: number
  deposits_collected_cents: number
  tips_cents: number
  top_design: { id: string; title: string; count: number } | null
  artist_id: string | null
}

export async function closeFlashEventAction(
  eventId: string
): Promise<ActionResult & { summary?: CloseOutSummary }> {
  const auth = await getAuthenticatedUser()
  if (!auth) return { success: false, error: 'Not authenticated' }
  if (!['owner', 'admin'].includes(auth.role)) {
    return { success: false, error: 'Only owners and admins can close events' }
  }

  try {
    const { createClient } = await import('@/lib/supabase/server')
    const supabase = await createClient()

    const rpc = supabase.rpc as unknown as (
      fn: 'close_flash_event',
      args: { p_event_id: string }
    ) => Promise<{ data: CloseOutSummary | null; error: { message: string } | null }>

    const { data, error } = await rpc('close_flash_event', { p_event_id: eventId })

    if (error) {
      logger.error({ error, eventId }, 'closeFlashEventAction RPC failed')
      return { success: false, error: error.message }
    }

    const summary = data as CloseOutSummary | null

    const { logAuditAction } = await import('@/lib/audit')
    await logAuditAction(
      auth.user.id,
      'flash_event.closed',
      { type: 'flash_event', id: eventId },
      { summary },
      auth.studioId
    )

    revalidatePath('/flash-events')
    revalidatePath(`/flash-events/${eventId}`)
    return { success: true, ...(summary ? { summary } : {}) }
  } catch (err) {
    logger.error({ err, eventId }, 'closeFlashEventAction failed')
    const message = err instanceof Error ? err.message : 'Failed to close event'
    return { success: false, error: message }
  }
}

