              label="Bookings"
              value={`${summary.completed_count} completed · ${summary.no_show_count} no-shows`}
            />
            <StatRow
              label="Slot revenue"
              value={formatCurrency(summary.slot_revenue_cents)}
              mono
            />
            <StatRow
              label="Deposits collected"
              value={formatCurrency(summary.deposits_collected_cents)}
              mono
            />
            <StatRow
              label="Tips"
              value={formatCurrency(summary.tips_cents)}
              mono
            />
