          <p className="text-sm text-muted-foreground py-1">No summary data returned.</p>
        )}

        <AlertDialogFooter>
          {/* TODO: wire email summary via Resend when postmark agent completes email-infra */}
          <Button variant="outline" disabled>
            Email me a copy
          </Button>
          <AlertDialogCancel asChild>
            <Button onClick={() => onOpenChange(false)}>Done</Button>
          </AlertDialogCancel>
        </AlertDialogFooter>
      </AlertDialogContent>
    </AlertDialog>
  )
}

function StatRow({
  label,
  value,
  mono = false,
}: {
  label: string
  value: string
  mono?: boolean
}) {
  return (
    <div className="flex items-baseline justify-between gap-4">
      <span
        className="text-xs font-bold uppercase tracking-[0.08em]"
